<script setup lang="ts">import {ref,computed} from 'vue';import {fmt,constraintReason} from '../utils/format';const p=defineProps<{trace:any;states:string[]}>(),conditional=computed(()=>p.trace.constraint_mode==='conditional'&&p.trace.constraint_status==='satisfied'),grid=ref<'unconstrained'|'conditional'>('unconstrained');</script><template><section class="posterior-grid"><div class="section-head"><h2>每个时刻，状态仍有分布。</h2><span>{{conditional?'无约束 / 条件后验分开查看':'前向×后向 / 序列likelihood归一'}}</span></div><div v-if="conditional" class="grid-switch"><button type="button" :class="{active:grid==='unconstrained'}" @click="grid='unconstrained'">无约束后验</button><button type="button" :class="{active:grid==='conditional'}" @click="grid='conditional'">条件后验</button></div><p v-if="p.trace.constraint_status==='conflict'" class="copper">标记冲突：第{{p.trace.constraint_conflict.first_infeasible_step}}步起无可行路径，后验不存在；上方的无约束似然仍保留（{{constraintReason(p.trace.constraint_conflict.reason)}}）。真实0不会以数值下溢展示。</p><div class="posterior-scroll"><div class="posterior-table" :style="{minWidth:Math.max(500,p.trace.tokens.length*24+125)+'px'}"><div class="posterior-row" v-for="(state,s) in states" :key="state"><strong>{{s}} / {{state}}</strong><span v-for="(row,t) in (grid==='conditional'&&conditional?p.trace.conditional_posterior:p.trace.posterior)" :key="t" class="posterior-cell" :style="{backgroundColor:'oklch(78% .08 88 / '+row[s]+')'}" :title="'t'+(Number(t)+1)+': '+fmt(row[s],8)"><small v-if="p.trace.tokens.length<=12" :style="{color:row[s]>.6?'var(--ink)':'var(--paper)'}">{{fmt(row[s],3)}}</small></span></div></div></div><div class="mark-summary" v-if="p.trace.constraints?.length"><span v-for="c in p.trace.constraints" :key="c.step"><b>第{{c.step}}步</b> 只允许状态 {{c.allowed_states.join(' / ')}}</span></div><p v-if="conditional">颜色来自{{grid==='conditional'?'满足标记的条件':'未加标记的原始'}}边际后验；每列和为1。条件后验不把无约束质量重新缩放后冒充条件结果，约束成立概率单独列出。</p><p v-else-if="p.trace.constraint_status==='conflict'">条件路径集合为空，因此不画条件后验；无约束后验与似然保持原样。</p><p v-else>颜色来自真实边际后验；每列和为1。状态标签由固定模型定义，不能直接等同设备故障。</p></section></template>
